 RunManifest m;m.id="crow_perch_restart";m.robot=hipRollModel();m.scene=makeBirdFlowAmericanCrowNavigationScenePack();m.sensors.id="proprioception";m.task=makeAmericanCrowEmbodiedTaskPack(m.sensors.observation,m.reality.reset);m.reality.reset={};m.reality.id="reality";m.teacher.id="no_teacher";m.profile.id="probe";m.profile.capacities={.candidatePairs=512,.rawContacts=2048,.manifolds=512,.constraintBlocks=cap,.constraintRows=cap*3};m.task.capacities=m.profile.capacities;m.profile.environmentCount=1;m.profile.controlSteps=1;m.profile.physicsSubsteps=1;m.profile.controlTimestepSeconds=.00125f;
 CompiledRun run;auto st=compileRun(m,run);need(st.succeeded(),st.message);auto q=run.model().defaultQ,v=run.model().defaultV;std::ifstream in("artifacts/crow-v15-perch-toe-collision-restart-20261111/snapshot.txt");for(auto& x:q)in>>x;for(auto& x:v)in>>x;auto original=run.defaultSceneBodies();std::vector<MRBodyStateGPU> scene(original.begin(),original.end());need(scene.size()==6,"scene body count");for(auto& body:scene){float z[13];for(auto&x:z)in>>x;body.position={z[0],z[1],z[2],1};body.orientation={z[3],z[4],z[5],z[6]};body.linearVelocityAndInverseMass.x=z[7];body.linearVelocityAndInverseMass.y=z[8];body.linearVelocityAndInverseMass.z=z[9];body.angularVelocity={z[10],z[11],z[12],0};}need(bool(in),"snapshot read");
